#if UNITY_EDITOR
using System;
using System.Linq;
using System.IO;
using LastRail.Battle;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode { public sealed class BFixedGeometryTests {
 static BDepartureSourceBundle Source()=>BSameRunSourceTests.Read(BSameRunSourceTests.Packet());
 static BOrdinaryGeometrySnapshot Asset()=>BOrdinaryGeometrySnapshot.Read(BOrdinaryGeometryTests.Asset(),BDirectAttackInput.Digest(BOrdinaryGeometryTests.Asset()));
 static JObject Authored(bool connected=true){var b=Source();var a=Asset();return new JObject{["version"]=BOrdinaryGeometryBinding.PreparedVersion,["geometryHash"]=a.Hash,["placementHash"]=BDirectAttackInput.Digest(b.PrepareFormation().Placement.Capture()),["bundleHash"]=b.PacketHash,["contextId"]=b.ContextId,["provenance"]="EXPLICIT_TEST_PHYSICAL_TRANSFORMS_NOT_OPERATING_GEOMETRY",["transformSource"]="Existing ordinary-b-test-carriage-v1 48000mm trial geometry; explicitly authored scene translations 0 and 49000mm with 1000mm bridge. Not slot-index inference, operating or art dimensions.",["sourceRevision"]=1,["instances"]=new JArray(new JObject{["slot"]=0,["carriageId"]="physical-0",["sourceDefinitionId"]="LOCAL_KIND",["generation"]=1,["positionMm"]=new JArray(0,0,0),["yawQuarterTurns"]=0},new JObject{["slot"]=4,["carriageId"]="physical-4",["sourceDefinitionId"]="LOCAL_KIND",["generation"]=1,["positionMm"]=new JArray(49000,0,0),["yawQuarterTurns"]=0}),["connections"]=connected?new JArray(new JObject{["fromSlot"]=0,["toSlot"]=4,["bridgeMm"]=new JArray(new JArray(24000,2400,0),new JArray(25000,2400,0))}):new JArray()};}
 static BOrdinaryGeometryBinding Geometry(JObject p=null){p=p??Authored();return Source().ReadPreparedGeometry(p,BDirectAttackInput.Digest(p),Asset());}
 static JObject Pose(string id,string kind,int slot,long x)=>new JObject{["entityId"]=id,["kind"]=kind,["originalPhysicalSlot"]=slot,["originalInstanceId"]="physical-"+slot,["physicalSlot"]=slot,["instanceId"]="physical-"+slot,["instanceGeneration"]=1,["entityGeneration"]=1,["pathRevision"]=0,["positionMm"]=new JArray(x,2400,0)};
 static JObject Poses(BOrdinaryGeometryBinding g,long tick=12,long revision=1)=>new JObject{["version"]=BPhysicalGeometryObservationOwner.Version,["sourceStatus"]="EXPLICIT_TEST_SPACE_OBSERVATIONS_NOT_NATIVE_EXECUTOR",["geometryHash"]=g.Hash,["bundleHash"]=g.OriginalBundleHash,["contextId"]=g.OriginalContextId,["observedTick"]=tick,["sourceRevision"]=revision,["poses"]=new JArray(Pose("op_kyle","OPERATOR",0,0),Pose("physical-0","CARRIAGE",0,0),Pose("physical-4","CARRIAGE",4,49000))};
 static void Publish(BPhysicalGeometryObservationOwner o,JObject p)=>o.Publish(p,BDirectAttackInput.Digest(p));
 static JObject Frame(BPhysicalGeometryObservationOwner o,string target="physical-4",long distance=24000)=>o.Observe("op_kyle",target,12,1,1,1,0,0,distance);
 [Test] public void OriginalSlotsAndSocketsUseExplicitTransformsWithoutHoleBodies(){var g=Geometry();CollectionAssert.AreEqual(new[]{0,4},g.OccupiedSlots);Assert.AreEqual(49000,(long)g.WorldPoint(4,new JArray(0,2400,0))[0]);Assert.Throws<ArgumentException>(()=>g.WorldPoint(1,new JArray(0,0,0)));Assert.AreEqual(49000,(long)g.WorldSocketPath(4,"left","climb")[2][0]);Assert.IsTrue(g.ConnectedPhysicalSlots(0,4));Assert.IsTrue(g.ConnectedPhysicalSlots(4,0));Assert.IsFalse(Geometry(Authored(false)).ConnectedPhysicalSlots(0,4));Assert.IsTrue(g.PhysicalPlacement.RequireCar(4,"physical-4").IsCargo);}
 [TestCase("geometryHash"),TestCase("placementHash"),TestCase("bundleHash"),TestCase("contextId"),TestCase("instance"),TestCase("slot"),TestCase("definition"),TestCase("duplicate"),TestCase("connector"),TestCase("yaw"),TestCase("provenance")]
 public void SubstitutedAuthoringIsRejectedEvenWhenRehashed(string fault){var p=Authored();if(fault=="instance")p["instances"][1]["carriageId"]="foreign";else if(fault=="slot")p["instances"][1]["slot"]=1;else if(fault=="definition")p["instances"][1]["sourceDefinitionId"]="foreign";else if(fault=="duplicate")p["instances"][1]=p["instances"][0].DeepClone();else if(fault=="connector")p["connections"][0]["bridgeMm"][1][0]=26000;else if(fault=="yaw")p["instances"][1]["yawQuarterTurns"]=4;else p[fault]="foreign";Assert.Throws<ArgumentException>(()=>Geometry(p));}
 [Test] public void RotationIsAnAuthoredTransformAndSocketKindsAreValidated(){var p=Authored(false);p["instances"][1]["yawQuarterTurns"]=1;var g=Geometry(p);CollectionAssert.AreEqual(new long[]{49000,2400,1000},g.WorldPoint(4,new JArray(1000,2400,0)).Values<long>());Assert.Throws<ArgumentException>(()=>g.WorldSocketPath(4,"left","teleport"));}
 [Test] public void CargoTargetKeepsOriginalSlotAndDistanceAndExportsTestProvenance(){var g=Geometry();var o=new BPhysicalGeometryObservationOwner(g,()=>12);var p=Poses(g);Publish(o,p);var f=Frame(o);Assert.AreEqual(4,(int)f["targetSlot"]);Assert.AreEqual(49000,(long)f["distanceMm"]);Assert.IsFalse((bool)f["eligible"]);Assert.AreEqual("TEST_SPACE_DISTANCE_LOS_NOT_COMBAT_APPROVAL",(string)f["sourceStatus"]);var dir="D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BFixedGeometry-20261006/";File.WriteAllText(dir+"explicit-test-physical-geometry.json",g.Capture().ToString());File.WriteAllText(dir+"original-tick-test-poses.json",p.ToString());File.WriteAllText(dir+"cargo-distance-frame.json",f.ToString());}
 [TestCase(6000),TestCase(12000),TestCase(24000)] public void ExactMillimetreRangeBoundaryUsesExistingGeometryMath(int distance){var g=Geometry();var o=new BPhysicalGeometryObservationOwner(g,()=>12);var p=Poses(g);p["poses"][1]["positionMm"][0]=distance;Publish(o,p);Assert.IsTrue((bool)Frame(o,"physical-0",distance)["eligible"]);Assert.IsFalse((bool)Frame(o,"physical-0",distance-1)["eligible"]);Assert.AreEqual(distance,(long)Frame(o,"physical-0",distance)["distanceMm"]);}
 [TestCase("tick"),TestCase("roof"),TestCase("generation"),TestCase("duplicate"),TestCase("context"),TestCase("kind"),TestCase("instance")]
 public void InvalidObservationBatchIsAtomic(string fault){var g=Geometry();var o=new BPhysicalGeometryObservationOwner(g,()=>12);var p=Poses(g);Publish(o,p);var bad=(JObject)p.DeepClone();bad["sourceRevision"]=2;if(fault=="tick")bad["observedTick"]=13;if(fault=="roof")bad["poses"][0]["positionMm"][1]=0;if(fault=="generation")bad["poses"][0]["instanceGeneration"]=2;if(fault=="duplicate")bad["poses"][2]=bad["poses"][1].DeepClone();if(fault=="context")bad["contextId"]="foreign";if(fault=="kind")bad["poses"][2]["kind"]="OPERATOR";if(fault=="instance")bad["poses"][0]["instanceId"]="physical-4";Assert.Throws<ArgumentException>(()=>Publish(o,bad));Assert.IsTrue(JToken.DeepEquals(p,o.Capture()));}
 [Test] public void DynamicCargoRoofPoseKeepsFrozenHomeAndNeedsActualConnection(){foreach(bool connected in new[]{true,false}){var g=Geometry(Authored(connected));var o=new BPhysicalGeometryObservationOwner(g,()=>12);var p=Poses(g);var actor=p["poses"][0];actor["physicalSlot"]=4;actor["instanceId"]="physical-4";actor["positionMm"][0]=49000;actor["pathRevision"]=1;if(!connected){Assert.Throws<ArgumentException>(()=>Publish(o,p));continue;}Publish(o,p);Assert.AreEqual(0,(int)o.Capture()["poses"][0]["originalPhysicalSlot"]);Assert.AreEqual(4,(int)o.Capture()["poses"][0]["physicalSlot"]);Assert.AreEqual(0,g.PhysicalPlacement.RequireActor(0,"physical-0","op_kyle").PhysicalSlot);}}
 [Test] public void OriginalTickGenerationPathAndRevisionFenceRestoreAndLaterReads(){long tick=12;var g=Geometry();var p=Poses(g);var o=BPhysicalGeometryObservationOwner.Restore(p,BDirectAttackInput.Digest(p),g,()=>tick);Assert.IsTrue(JToken.DeepEquals(p,o.Capture()));Assert.Throws<ArgumentException>(()=>o.Observe("op_kyle","physical-4",12,1,2,1,0,0,24000));Assert.Throws<ArgumentException>(()=>o.Observe("op_kyle","physical-4",12,1,1,1,1,0,24000));Assert.Throws<ArgumentException>(()=>o.Observe("op_kyle","physical-4",12,2,1,1,0,0,24000));tick=13;Assert.Throws<ArgumentException>(()=>Frame(o));var next=Poses(g,13,2);next["poses"][0]["pathRevision"]=2;Publish(o,next);var old=(JObject)next.DeepClone();old["sourceRevision"]=3;old["poses"][0]["pathRevision"]=1;Assert.Throws<ArgumentException>(()=>Publish(o,old));Assert.IsTrue(JToken.DeepEquals(next,o.Capture()));}
 [Test] public void BorrowedClockCannotReenterOrChangeDuringAtomicPublish(){var g=Geometry();var p=Poses(g);BPhysicalGeometryObservationOwner o=null;bool reenter=true;int reads=0;o=new BPhysicalGeometryObservationOwner(g,()=>{if(reenter){reenter=false;Assert.Throws<InvalidOperationException>(()=>Publish(o,p));}return ++reads==1?12:13;});Assert.Throws<ArgumentException>(()=>Publish(o,p));Assert.Throws<InvalidOperationException>(()=>o.Capture());}
 }}
#endif
